import{_ as a,o as t,c as o,a2 as i}from"./chunks/framework.BXzK3EA4.js";const u=JSON.parse('{"title":"Changelog","description":"","frontmatter":{},"headers":[],"relativePath":"guide/changelog.md","filePath":"guide/changelog.md"}'),n={name:"guide/changelog.md"};function r(l,e,s,d,c,g){return t(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="changelog" tabindex="-1">Changelog <a class="header-anchor" href="#changelog" aria-label="Permalink to &quot;Changelog&quot;">​</a></h1><p>All notable changes to the FOSSBilling project will be documented in this file.</p><hr><h2 id="_2-0-0-golang-2026-09-08" tabindex="-1">[2.0.0-golang] - 2026-09-08 <a class="header-anchor" href="#_2-0-0-golang-2026-09-08" aria-label="Permalink to &quot;[2.0.0-golang] - 2026-09-08&quot;">​</a></h2><p>This is a major milestone release transitioning FOSSBilling to a Cloud-Native Go backend and React frontend ecosystem.</p><h3 id="added" tabindex="-1">Added <a class="header-anchor" href="#added" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li><strong>Core Engine:</strong> Brand new Golang 1.22+ backend with Clean Architecture.</li><li><strong>Modern UI:</strong> React-based portals for both Clients and Administrators with Tailwind CSS.</li><li><strong>Multi-Driver Provisioning:</strong> Native support for cPanel, DirectAdmin, Plesk, HestiaCP, and CWP.</li><li><strong>Custom Formbuilder:</strong> Ability to create custom technical fields for product checkouts.</li><li><strong>Notification Center:</strong> Real-time in-app alerts for payment and service status changes.</li><li><strong>Security:</strong> Integrated honeypot, anti-XSS, and disposable email blocking.</li></ul><h3 id="changed" tabindex="-1">Changed <a class="header-anchor" href="#changed" aria-label="Permalink to &quot;Changed&quot;">​</a></h3><ul><li>Migrated primary database from MySQL to <strong>PostgreSQL 16</strong>.</li><li>Optimized money arithmetic using <code>int64</code> cent-precision to avoid floating point errors.</li><li>Improved API performance with sub-millisecond response times.</li></ul><hr><h2 id="_1-x-x-legacy" tabindex="-1">[1.x.x] - Legacy <a class="header-anchor" href="#_1-x-x-legacy" aria-label="Permalink to &quot;[1.x.x] - Legacy&quot;">​</a></h2><p>Refer to the <code>backend-php/</code> folder for legacy PHP source code and history. New features are exclusively developed on the 2.x Go branch.</p>',12)])])}const p=a(n,[["render",r]]);export{u as __pageData,p as default};
